'use client';

import type { Variants } from 'motion/react';
import type { HTMLAttributes } from 'react';
import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
} from 'react';
import { motion, useAnimation, useReducedMotion } from 'motion/react';

import { cn } from '@/lib/utils';

export interface PhosphorAlarmIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}
interface PhosphorAlarmIconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}

const ICON_VARIANTS: Variants = {
  normal: {
    x: 0,
    y: 0,
    rotate: 0,
    scale: 1,
    scaleX: 1,
    scaleY: 1,
    opacity: 1,
    transition: { duration: 0.18, ease: 'easeOut' },
  },
  animate: { 'transition': { 'duration': 0.75, 'ease': 'easeInOut' } },
};

const DETAIL_0_VARIANTS: Variants = {
  normal: {
    'rotate': 0,
    'transition': { 'duration': 0.18, 'ease': 'easeOut' },
  },
  animate: {
    'rotate': [0, -15, 10, -8, 0],
    'transition': { 'duration': 0.65, 'delay': 0, 'ease': 'easeInOut' },
  },
};

const DETAIL_1_VARIANTS: Variants = {
  normal: {
    'rotate': 0,
    'transition': { 'duration': 0.18, 'ease': 'easeOut' },
  },
  animate: {
    'rotate': [0, 15, -10, 8, 0],
    'transition': { 'duration': 0.65, 'delay': 0, 'ease': 'easeInOut' },
  },
};

const DETAIL_2_VARIANTS: Variants = {
  normal: {
    'rotate': 0,
    'transition': { 'duration': 0.18, 'ease': 'easeOut' },
  },
  animate: {
    'rotate': [0, 30, 0],
    'transition': { 'duration': 0.8, 'delay': 0, 'ease': 'easeInOut' },
  },
};

const PhosphorAlarmIcon = forwardRef<
  PhosphorAlarmIconHandle,
  PhosphorAlarmIconProps
>(
  (
    {
      onMouseEnter,
      onMouseLeave,
      onFocus,
      onBlur,
      className,
      size = 28,
      ...props
    },
    ref
  ) => {
    const controls = useAnimation();
    const reducedMotion = useReducedMotion();
    const sequence = useRef(0);
    const startAnimation = useCallback(() => {
      const current = ++sequence.current;
      controls.stop();
      controls.set('normal');
      if (reducedMotion) return;
      void controls.start('animate').then(() => {
        if (sequence.current === current) controls.set('normal');
      });
    }, [controls, reducedMotion]);
    const stopAnimation = useCallback(() => {
      sequence.current += 1;
      void controls.start('normal');
    }, [controls]);
    useImperativeHandle(ref, () => ({ startAnimation, stopAnimation }), [
      startAnimation,
      stopAnimation,
    ]);
    useEffect(() => {
      if (reducedMotion) {
        sequence.current += 1;
        controls.set('normal');
      }
      return () => {
        sequence.current += 1;
        controls.stop();
      };
    }, [controls, reducedMotion]);
    return (
      <div
        {...props}
        className={cn(className)}
        onMouseEnter={(event) => {
          if (!ref) startAnimation();
          onMouseEnter?.(event);
        }}
        onMouseLeave={(event) => {
          if (!ref) stopAnimation();
          onMouseLeave?.(event);
        }}
        onFocus={(event) => {
          if (!ref) startAnimation();
          onFocus?.(event);
        }}
        onBlur={(event) => {
          if (!ref) stopAnimation();
          onBlur?.(event);
        }}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox="0 0 256 256"
          fill="currentColor"
          overflow="visible"
          aria-hidden="true"
          focusable="false"
        >
          <motion.g
            initial="normal"
            animate={controls}
            variants={ICON_VARIANTS}
            style={{ transformOrigin: '128px 128px' }}
          >
            <path d="M128,40a96,96,0,1,0,96,96A96.11,96.11,0,0,0,128,40ZM128,216a80,80,0,1,1,80-80A80.09,80.09,0,0,1,128,216Z" />
            <motion.path
              d="M61.66,37.66l-32,32A8,8,0,0,1,18.34,58.34l32-32A8,8,0,0,1,61.66,37.66Z"
              variants={DETAIL_0_VARIANTS}
              style={{ transformOrigin: '40px 48px' }}
            />
            <motion.path
              d="M237.66,69.66a8,8,0,0,1-11.32,0l-32-32a8,8,0,0,1,11.32-11.32l32,32A8,8,0,0,1,237.66,69.66Z"
              variants={DETAIL_1_VARIANTS}
              style={{ transformOrigin: '216px 48px' }}
            />
            <motion.path
              d="M184,128a8,8,0,0,1,0,16H128a8,8,0,0,1-8-8V80a8,8,0,0,1,16,0v48Z"
              variants={DETAIL_2_VARIANTS}
              style={{ transformOrigin: '128px 136px' }}
            />
          </motion.g>
        </svg>
      </div>
    );
  }
);
PhosphorAlarmIcon.displayName = 'PhosphorAlarmIcon';
export { PhosphorAlarmIcon };
